import type { Page } from '@playwright/test';
import { test,expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import { createServer,type ViteDevServer } from 'vite';
import { fileURLToPath } from 'node:url';
import { mkdir } from 'node:fs/promises';
test.describe.configure({mode:'serial'});
let server:ViteDevServer,url:string;
const evidence=fileURLToPath(new URL('../evidence/',import.meta.url));
test.beforeAll(async()=>{
  server=await createServer({configFile:false,root:fileURLToPath(new URL('../fixtures/',import.meta.url)),esbuild:{jsx:'automatic'},server:{host:'127.0.0.1',port:0,fs:{allow:[fileURLToPath(new URL('../../../../../../',import.meta.url))]}},logLevel:'silent'});
  await server.listen();const address=server.httpServer!.address();if(!address || typeof address==='string')throw new Error();url=`http://127.0.0.1:${address.port}`;await mkdir(evidence,{recursive:true});
});
test.afterAll(async()=>{await server?.close();});
async function ready(page:Page,suffix=''){await page.setViewportSize({width:800,height:600});await page.goto(url+suffix);await expect(page.getByRole('searchbox',{name:'Search commands'})).toBeVisible();await page.evaluate(()=>document.fonts.ready);}
for(const theme of ['dark','light'])test(`${theme} real shared launcher rendering and accessible screenshot`,async({page})=>{
  await ready(page,`?theme=${theme}`);await expect(page.getByRole('option')).toHaveCount(3);await expect(page.getByRole('option',{name:/Local data/})).toHaveAttribute('aria-selected','true');
  expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-launcher.png`,fullPage:true});
});
test('query arrows, list Home/End, native query caret and Enter dispatch one stable command intent',async({page})=>{
  await ready(page);const query=page.getByRole('searchbox',{name:'Search commands'});await expect(query).toBeFocused();await query.press('ArrowDown');await expect(page.getByRole('option',{name:/Hide Linuxcast/})).toHaveAttribute('aria-selected','true');
  const list=page.getByRole('listbox');await list.focus();await list.press('End');await expect(page.getByRole('option',{name:/Quit Linuxcast/})).toHaveAttribute('aria-selected','true');await list.press('Home');await expect(page.getByRole('option',{name:/Local data/})).toHaveAttribute('aria-selected','true');
  await query.fill('privacy');await expect(page.getByRole('option')).toHaveCount(1);await query.press('Home');await expect(query).toBeFocused();await query.press('Enter');await expect(page.locator('output')).toHaveText('Requested linuxcast:open-local-data.');
});
test('Ctrl K actions preserve focus and Escape dismisses only after closing actions',async({page})=>{
  await ready(page);const query=page.getByRole('searchbox',{name:'Search commands'});await query.press('Control+k');await expect(page.getByRole('dialog',{name:'Actions'})).toBeVisible();await page.keyboard.press('Escape');await expect(page.getByRole('dialog')).not.toBeVisible();await expect(query).toBeFocused();await expect(page.locator('output')).toHaveText('No command requested.');await query.press('Escape');await expect(page.locator('output')).toHaveText('Requested Hide.');await expect(query).toBeVisible();
});
test('disabled commands remain discoverable and cannot execute',async({page})=>{
  await ready(page,'?state=disabled');const query=page.getByRole('searchbox',{name:'Search commands'});await query.fill('data');await expect(page.getByRole('option')).toHaveAttribute('aria-disabled','true');await query.press('Enter');await expect(page.locator('output')).toHaveText('No command requested.');await expect(page.getByRole('option')).toContainText('Reopen Linuxcast');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/dark-unavailable.png`,fullPage:true});
});
test('loading, filtered-empty and failed execution are explicit safe states',async({page})=>{
  await ready(page,'?state=loading');await expect(page.getByRole('status').filter({hasText:'Loading…'})).toBeVisible();await page.screenshot({path:`${evidence}/dark-loading.png`,fullPage:true});
  await ready(page);await page.getByRole('searchbox').fill('unmatched fixture');await expect(page.getByRole('heading',{name:'No matching results'})).toBeVisible();await page.screenshot({path:`${evidence}/dark-empty.png`,fullPage:true});
  await ready(page,'?state=execution-error');await page.getByRole('searchbox').fill('data');await page.getByRole('searchbox').press('Enter');await expect(page.getByRole('alert')).toContainText('outcome is unknown');await expect(page.locator('body')).not.toContainText('synthetic fixture error');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/dark-error.png`,fullPage:true});
});

test('held Enter cannot dispatch from the action-panel query',async({page})=>{
  await ready(page);await page.getByRole('searchbox',{name:'Search commands'}).press('Control+k');const actionQuery=page.getByRole('searchbox',{name:'Find an action'});await actionQuery.dispatchEvent('keydown',{key:'Enter',code:'Enter',repeat:true,bubbles:true,cancelable:true});await expect(page.locator('output')).toHaveText('No command requested.');await expect(page.getByRole('dialog',{name:'Actions'})).toBeVisible();await actionQuery.press('Enter');await expect(page.locator('output')).toHaveText('Requested linuxcast:open-local-data.');
});
for(const theme of ['dark','light'])test(`${theme} keyboard pin/unpin preserves command identity and primary action`,async({page})=>{
  await ready(page,`?theme=${theme}`);const query=page.getByRole('searchbox',{name:'Search commands'});await query.press('ArrowDown');
  await query.press('Control+k');await page.getByRole('searchbox',{name:'Find an action'}).fill('Pin command');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');
  const hide=page.getByRole('option',{name:/Hide Linuxcast/});await expect(hide).toHaveAttribute('aria-selected','true');await expect(hide).toContainText('Pinned');await expect(page.getByRole('option').first()).toContainText('Hide Linuxcast');await expect(page.getByRole('button',{name:'Hide Enter',exact:true})).toBeVisible();await expect(query).toBeFocused();
  expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-pinned-command.png`,fullPage:true});
  await query.press('Control+k');await page.getByRole('searchbox',{name:'Find an action'}).fill('Unpin command');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');
  await expect(hide).not.toContainText('Pinned');await expect(hide).toHaveAttribute('aria-selected','true');await expect(page.getByRole('option').first()).toContainText('Local data');await expect(page.locator('output')).toHaveText('Requested unpin for linuxcast:hide.');
});
test('pending pin does not display saved state or run the selected command',async({page})=>{
  await ready(page,'?state=pin-pending');const query=page.getByRole('searchbox',{name:'Search commands'});await query.press('Control+k');const action=page.getByRole('searchbox',{name:'Find an action'});await action.fill('Pin command');await action.press('Enter');
  const selected=page.getByRole('option',{name:/Local data/});await expect(selected).toHaveAttribute('aria-disabled','true');await expect(selected).not.toContainText('Pinned');await query.press('Enter');await expect(page.locator('output')).toHaveText('Requested pin for linuxcast:open-local-data.');await expect(selected).toContainText('Pinned');await expect(selected).toHaveAttribute('aria-disabled','false');
});
test('pin failure and unavailable storage expose safe reload remediation',async({page})=>{
  await ready(page,'?state=pin-failed');const query=page.getByRole('searchbox',{name:'Search commands'});await query.press('Control+k');await page.getByRole('searchbox',{name:'Find an action'}).fill('Pin command');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');
  await expect(page.getByRole('alert')).toContainText('could not be confirmed');await expect(page.getByRole('option').first()).not.toContainText('Pinned');await expect(page.locator('body')).not.toContainText('synthetic pin error');await page.screenshot({path:`${evidence}/dark-pin-unconfirmed.png`,fullPage:true});
  await ready(page,'?state=ranking-unavailable');await page.getByRole('searchbox',{name:'Search commands'}).press('Control+k');const pin=page.getByRole('button',{name:/^Pin command/});await expect(pin).toHaveAttribute('aria-disabled','true');await expect(pin).toContainText('Reload commands');await page.getByRole('searchbox',{name:'Find an action'}).fill('Pin command');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');await expect(page.locator('output')).toHaveText('No command requested.');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/dark-pin-unavailable.png`,fullPage:true});
});

for(const theme of ['dark','light'])test(`${theme} paged applications search and keyboard pin preserves Open and other pages`,async({page})=>{
  await ready(page,`?state=applications&theme=${theme}`);await expect(page.getByRole('option')).toHaveCount(5);const query=page.getByRole('searchbox',{name:'Search commands'});await query.fill('Public');await expect(page.getByRole('option')).toHaveCount(2);await expect(page.getByText('Applications',{exact:true})).toBeVisible();await query.press('ArrowDown');await expect(page.getByRole('option',{name:/Public Notes/})).toHaveAttribute('aria-selected','true');await query.press('ArrowUp');
  const calculator=page.getByRole('option',{name:/Public Calculator/});await expect(calculator).toHaveAttribute('aria-selected','true');await expect(page.getByRole('button',{name:'Open Enter',exact:true})).toBeVisible();
  await query.press('Control+k');await page.getByRole('searchbox',{name:'Find an action'}).fill('Pin command');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');await expect(calculator).toContainText('Pinned');await expect(calculator).toHaveAttribute('aria-selected','true');await expect(page.getByRole('button',{name:'Open Enter',exact:true})).toBeVisible();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-applications.png`,fullPage:true});
  await query.press('Enter');await expect(page.locator('output')).toHaveText(`Requested application:${'2'.repeat(64)}.`);await query.fill('Notes');await expect(page.getByRole('option',{name:/Public Notes/})).toBeVisible();await query.fill('data');await expect(page.getByRole('option',{name:/Local data/})).toBeVisible();
});
test('application unavailability and uncertain launch stay actionable without claiming success',async({page})=>{
  await ready(page,'?state=applications-unavailable');await expect(page.getByRole('option')).toHaveCount(3);await expect(page.getByText('Applications are unavailable. Reload commands to try again.',{exact:true})).toBeVisible();await page.screenshot({path:`${evidence}/dark-applications-unavailable.png`,fullPage:true});
  await ready(page,'?state=application-unknown');await page.getByRole('searchbox',{name:'Search commands'}).fill('Notes');await page.getByRole('searchbox',{name:'Search commands'}).press('Enter');await expect(page.getByRole('alert')).toContainText('outcome is unknown');await expect(page.locator('body')).not.toContainText('Synthetic private detail');await page.screenshot({path:`${evidence}/dark-application-unknown.png`,fullPage:true});
});

async function editAlias(page:Page){
  await page.getByRole('searchbox',{name:'Search commands'}).press('Control+k');const action=page.getByRole('searchbox',{name:'Find an action'});await action.fill('Edit search alias');await action.press('Enter');await expect(page.getByRole('form',{name:'Edit search alias'})).toBeVisible();
}
for(const theme of ['dark','light'])test(`${theme} shared alias Form saves/removes exact aliases and preserves root identity/primary`,async({page})=>{
  await ready(page,`?state=alias&theme=${theme}`);const query=page.getByRole('searchbox',{name:'Search commands'});await query.fill('hide');await editAlias(page);const field=page.getByRole('textbox',{name:'Search alias',exact:true});await expect(field).toHaveValue('conceal');await expect(field).toBeFocused();await expect(page.getByText(/Find Hide Linuxcast by an exact alias/)).toBeVisible();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-alias-form.png`,fullPage:true});
  await field.fill('  public-hide  ');await field.press('Tab');await expect(page.getByRole('button',{name:'Save alias',exact:true})).toBeFocused();await page.keyboard.press('Enter');await expect(page.getByRole('form')).not.toBeVisible();await expect(query).toHaveValue('hide');await expect(query).toBeFocused();await expect(page.getByRole('option',{name:/Hide Linuxcast/})).toHaveAttribute('aria-selected','true');await expect(page.getByRole('button',{name:'Hide Enter',exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText('Requested alias public-hide for linuxcast:hide.');
  await query.fill('public-hide');await expect(page.getByRole('option')).toHaveCount(1);await expect(page.getByRole('option')).toContainText('Hide Linuxcast');await editAlias(page);await expect(field).toHaveValue('public-hide');await field.fill('');await page.getByRole('button',{name:'Save alias',exact:true}).press('Enter');await expect(page.getByRole('form')).not.toBeVisible();await query.fill('public-hide');await expect(page.getByRole('option')).toHaveCount(0);await expect(page.locator('output')).toHaveText('Requested alias removal for linuxcast:hide.');await query.fill('Public');await expect(page.getByRole('option')).toHaveCount(2);
});
test('alias cancel and dirty Escape restore the root query/selection without execution',async({page})=>{
  await ready(page,'?state=alias');const query=page.getByRole('searchbox',{name:'Search commands'});await query.fill('hide');await editAlias(page);await page.getByRole('button',{name:'Cancel',exact:true}).press('Enter');await expect(query).toHaveValue('hide');await expect(query).toBeFocused();await editAlias(page);const field=page.getByRole('textbox',{name:'Search alias',exact:true});await field.fill('unsent alias');await field.press('Escape');await expect(page.getByRole('dialog',{name:'Discard this draft?'})).toBeVisible();await page.getByRole('button',{name:'Keep editing',exact:true}).press('Enter');await expect(field).toHaveValue('unsent alias');await field.press('Escape');await page.getByRole('button',{name:'Discard changes',exact:true}).press('Enter');await expect(query).toBeFocused();await expect(query).toHaveValue('hide');await expect(page.getByRole('option',{name:/Hide Linuxcast/})).toHaveAttribute('aria-selected','true');await expect(page.locator('output')).toHaveText('No command requested.');
});
for(const theme of ['dark','light'])test(`${theme} alias collision and invalid drafts remain inline and editable`,async({page})=>{
  await ready(page,`?state=alias&theme=${theme}`);await page.getByRole('searchbox',{name:'Search commands'}).fill('hide');await editAlias(page);const field=page.getByRole('textbox',{name:'Search alias',exact:true});await field.fill('quit');await page.getByRole('button',{name:'Save alias',exact:true}).press('Enter');await expect(field).toHaveValue('quit');await expect(field).toHaveAttribute('aria-invalid','true');await expect(page.getByText('This alias is already used by another command. Choose another alias.',{exact:true})).toBeVisible();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-alias-conflict.png`,fullPage:true});
  await field.fill('😀'.repeat(65));await page.getByRole('button',{name:'Save alias',exact:true}).press('Enter');await expect(field).toHaveValue('😀'.repeat(65));await expect(page.getByText('Use up to 64 characters without control characters.',{exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText('Requested alias quit for linuxcast:hide.');
  await field.fill('fixed-alias');await page.getByRole('button',{name:'Save alias',exact:true}).press('Enter');await expect(page.getByRole('form')).not.toBeVisible();await page.getByRole('searchbox',{name:'Search commands'}).fill('fixed-alias');await expect(page.getByRole('option')).toContainText('Hide Linuxcast');
});
test('pending alias acknowledgement disables repeat submission and keeps saved metadata unchanged',async({page})=>{
  await ready(page,'?state=alias-pending');await page.getByRole('searchbox',{name:'Search commands'}).fill('hide');await editAlias(page);const field=page.getByRole('textbox',{name:'Search alias',exact:true});await field.fill('waiting-alias');await field.press('Enter');const save=page.getByRole('button',{name:'Save alias',exact:true});await expect(save).toBeDisabled();await expect(field).toBeDisabled();await field.dispatchEvent('keydown',{key:'Enter',code:'Enter',repeat:true,bubbles:true,cancelable:true});await expect(page.locator('output')).toHaveText('Requested alias waiting-alias for linuxcast:hide.');await expect(page.getByRole('form')).not.toBeVisible();
});
for(const theme of ['dark','light'])test(`${theme} uncertain alias requires explicit Reload and never shows a saved claim`,async({page})=>{
  await ready(page,`?state=alias-failed&theme=${theme}`);const query=page.getByRole('searchbox',{name:'Search commands'});await query.fill('hide');await editAlias(page);const field=page.getByRole('textbox',{name:'Search alias',exact:true});await field.fill('uncertain-alias');await field.press('Enter');await expect(page.getByRole('form')).toBeVisible();await expect(page.getByRole('alert')).toContainText('could not be confirmed');await expect(field).toHaveValue('uncertain-alias');await expect(page.getByRole('button',{name:'Save alias',exact:true})).toBeDisabled();await expect(page.locator('body')).not.toContainText('synthetic private alias error');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-alias-unconfirmed.png`,fullPage:true});
  await field.press('Control+k');await page.getByRole('searchbox',{name:'Find an action'}).fill('Reload commands');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');await expect(page.getByRole('form')).not.toBeVisible();await expect(query).toHaveValue('hide');await query.fill('uncertain-alias');await expect(page.getByRole('option')).toHaveCount(0);await query.fill('hide');await editAlias(page);await expect(field).toHaveValue('conceal');await expect(page.locator('output')).toHaveText('Requested alias uncertain-alias for linuxcast:hide.');
});

test('known alias storage failure retains draft and exposes working Reload in Form Actions',async({page})=>{
  await ready(page,'?state=alias-unavailable');await page.getByRole('searchbox',{name:'Search commands'}).fill('hide');await editAlias(page);const field=page.getByRole('textbox',{name:'Search alias',exact:true});await field.fill('retained');await field.press('Enter');await expect(field).toHaveValue('retained');await expect(page.getByText('Aliases are unavailable. Reload commands to reconnect to storage.',{exact:true})).toBeVisible();await field.press('Control+k');await page.getByRole('searchbox',{name:'Find an action'}).fill('Reload commands');await page.getByRole('searchbox',{name:'Find an action'}).press('Enter');await expect(page.getByRole('form')).not.toBeVisible();await editAlias(page);await expect(field).toHaveValue('conceal');await expect(page.locator('output')).toHaveText('Requested alias retained for linuxcast:hide.');
});

async function openUrlForm(page:Page,query='Open URL'){
  const search=page.getByRole('searchbox',{name:'Search commands'});await search.fill(query);await expect(page.getByRole('option',{name:/^Open URL/})).toBeVisible();await search.press('Enter');await expect(page.getByRole('form',{name:'Open URL',exact:true})).toBeVisible();
}
for(const theme of ['dark','light'])test(`${theme} typed URL opens shared Form with canonical address and only submits on explicit Open URL`,async({page})=>{
  await ready(page,`?state=url&theme=${theme}`);const external:string[]=[];page.on('request',request=>{if(!request.url().startsWith(url))external.push(request.url());});
  const typed='HTTPS://例え.example:443/public',canonical='https://xn--r8jz45g.example/public';await openUrlForm(page,typed);const field=page.getByRole('textbox',{name:'URL (required)',exact:true});await expect(field).toHaveValue(canonical);await expect(field).toBeFocused();await expect(page.locator('output')).toHaveText('No command requested.');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-url-form.png`,fullPage:true});
  await field.press('Tab');await expect(page.getByRole('button',{name:'Open URL',exact:true})).toBeFocused();await page.keyboard.press('Enter');await expect(page.getByRole('form')).not.toBeVisible();const query=page.getByRole('searchbox',{name:'Search commands'});await expect(query).toHaveValue(typed);await expect(query).toBeFocused();await expect(page.getByRole('option',{name:/^Open URL/})).toHaveAttribute('aria-selected','true');await expect(page.getByRole('button',{name:'Open URL Enter',exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText(`Requested URL ${canonical}.`);expect(external).toEqual([]);
});
for(const theme of ['dark','light'])test(`${theme} invalid URL stays inline and editable without dispatch or external requests`,async({page})=>{
  await ready(page,`?state=url&theme=${theme}`);const external:string[]=[];page.on('request',request=>{if(!request.url().startsWith(url))external.push(request.url());});await openUrlForm(page);const field=page.getByRole('textbox',{name:'URL (required)',exact:true});await expect(field).toHaveValue('');await field.fill('https://user:password@example.org/');await field.press('Enter');await expect(field).toHaveValue('https://user:password@example.org/');await expect(field).toHaveAttribute('aria-invalid','true');await expect(page.getByText('Enter an HTTP or HTTPS address without credentials, spaces or control characters.',{exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText('No command requested.');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-url-invalid.png`,fullPage:true});
  await field.fill('http://example.org/public');await field.press('Enter');await expect(page.getByRole('form')).not.toBeVisible();await expect(page.locator('output')).toHaveText('Requested URL http://example.org/public.');expect(external).toEqual([]);
});
